<?= $this->extend('layout') ?><?= $this->section('content') ?><h2>Impor Log Fingerprint</h2><p class="text-secondary">Pilih sumber mesin sesuai file yang disalin dari flashdisk.</p><div class="card p-4"><form method="post" action="/impor/preview" enctype="multipart/form-data"><?= csrf_field() ?><div class="mb-3"><label class="form-label">Sumber mesin</label><select class="form-select" name="device_id" required><option value="">Pilih mesin</option><?php foreach ($devices as $device): ?><option value="<?= esc($device['id']) ?>"><?= esc($device['device_name']) ?> — <?= esc($device['model_name']) ?> (<?= esc($device['unit_scope']) ?>)</option><?php endforeach ?></select></div><div class="mb-3"><label class="form-label">File log TXT</label><input type="file" class="form-control" name="log_file" accept=".txt" required></div><div class="alert alert-info">File asli tidak diubah. Sistem menampilkan pratinjau sebelum penyimpanan.</div><button class="btn btn-primary">Baca & pratinjau</button></form></div><?= $this->endSection() ?>